const CFG = {
  mode: 'keys',
  project_id: '225008626a33e62b328c63.04676982',
  langs: ["nl"],
  qa_check: '',
  lang_ids: '',
  filter_tags: '',
  filter_untranslated: 0
};

const BASE = 'https://api.lokalise.com/api2';

if (CFG.mode === 'projects') {
  return [{ json: { mode: 'projects', langs: CFG.langs, url: BASE + '/projects?limit=100' } }];
}
if (CFG.mode === 'languages') {
  return [{ json: { mode: 'languages', langs: CFG.langs, url: BASE + '/projects/' + CFG.project_id + '/languages?limit=500' } }];
}
if (CFG.mode === 'glossary') {
  return [{ json: { mode: 'glossary', langs: CFG.langs, url: BASE + '/projects/' + CFG.project_id + '/glossary-terms?limit=500' } }];
}
let qs = 'include_translations=1&disable_references=1&limit=500&pagination=cursor';
if (CFG.filter_tags) { qs += '&filter_tags=' + encodeURIComponent(CFG.filter_tags); }
if (CFG.filter_untranslated) { qs += '&filter_untranslated=1'; }
if (CFG.qa_check) { qs += '&filter_qa_issues=' + encodeURIComponent(CFG.qa_check); }
if (CFG.lang_ids) { qs += '&filter_translation_lang_ids=' + encodeURIComponent(CFG.lang_ids); }
return [{ json: { mode: 'keys', langs: CFG.langs, url: BASE + '/projects/' + CFG.project_id + '/keys?' + qs } }];

const cfg = $('Config').first().json;
const mode = cfg.mode;
const want = new Set(cfg.langs || []);
const pages = $input.all();
const errors = [];
const bodies = [];

for (const p of pages) {
  const r = p.json || {};
  const status = r.statusCode;
  const body = r.body !== undefined ? r.body : r;
  if (status !== undefined && status !== 200) {
    errors.push({ status: status, body: typeof body === 'string' ? body.slice(0, 400) : JSON.stringify(body).slice(0, 400) });
    continue;
  }
  bodies.push(body);
}

if (mode === 'glossary') {
  const out = [];
  for (const b of bodies) {
    const data = b.data || b.glossary_terms || [];
    for (const t of data) {
      const tr = {};
      for (const x of (t.translations || [])) {
        const iso = x.langId || x.lang_id || x.lang_iso;
        tr[iso] = { text: x.translation, desc: x.description || '' };
      }
      out.push({ id: t.id, term: t.term, description: t.description || '',
        caseSensitive: !!t.caseSensitive, translatable: t.translatable !== false,
        forbidden: !!t.forbidden, tags: t.tags || [],
        updatedAt: t.updatedAt || t.updated_at || '', translations: tr });
    }
  }
  return [{ json: { mode: mode, total: out.length, errors: errors, terms: out } }];
}

if (mode === 'projects') {
  const out = [];
  for (const b of bodies) {
    for (const p of (b.projects || [])) {
      out.push({ id: p.project_id, name: p.name, keys: (p.statistics || {}).keys_total || 0, base: p.base_language_iso });
    }
  }
  out.sort(function (a, b) { return a.name.toLowerCase().localeCompare(b.name.toLowerCase()); });
  return [{ json: { mode: mode, count: out.length, projects: out, errors: errors } }];
}

if (mode === 'languages') {
  const out = [];
  for (const b of bodies) {
    for (const l of (b.languages || [])) { out.push({ id: l.lang_id, iso: l.lang_iso, name: l.lang_name }); }
  }
  return [{ json: { mode: mode, count: out.length, languages: out, errors: errors } }];
}

const rows = [];
let total = 0;
let sourceMissing = 0;
const seen = {};
for (const b of bodies) {
  for (const k of (b.keys || [])) {
    total++;
    const plat = k.key_name || {};
    const name = plat.web || plat.ios || plat.android || plat.other || '';
    const t = {};
    const m = {};
    let en = '';
    for (const tr of (k.translations || [])) {
      const iso = tr.language_iso;
      if (iso !== 'en') { seen[iso] = 1; }
      const val = tr.translation;
      const s = (typeof val === 'string') ? val : JSON.stringify(val);
      if (iso === 'en') { en = s; continue; }
      if (want.size && !want.has(iso)) { continue; }
      if (!s || !s.trim()) { continue; }
      t[iso] = s;
      m[iso] = [tr.modified_at || '', tr.is_reviewed ? 1 : 0, tr.is_unverified ? 1 : 0].join('|');
    }
    if (!en || !en.trim()) { sourceMissing++; }
    if (Object.keys(t).length === 0) { continue; }
    rows.push({ k: name, en: en, t: t, m: m });
  }
}
return [{ json: { mode: 'keys', keys_seen: total, rows_kept: rows.length, source_missing: sourceMissing, langs_requested: cfg.langs || [], langs_in_project: Object.keys(seen).sort(), errors: errors, rows: rows } }];
